//! Cargo-driven `advapi32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is advapi32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x7c1d0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ffb4000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ffb4000000u64)),
        o => panic!("advapi32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:wine", "engine:pseh", "import:secur32", "import:advapi32_vista", "import:rpcrt4", "import:kernel32", "import:ntdll", "engine:cryptlib_rust", "engine:chkstk", "engine:delayimp_rust"],
        "x86_64" => &["body", "engine:wine", "engine:pseh", "import:secur32", "import:advapi32_vista", "import:rpcrt4", "import:kernel32", "import:ntdll", "engine:cryptlib_rust", "engine:delayimp_rust"],
        "aarch64" => &["body", "engine:wine", "engine:pseh", "import:secur32", "import:advapi32_vista", "import:rpcrt4", "import:kernel32", "import:ntdll", "engine:cryptlib_rust", "engine:chkstk", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/advapi32",
        "dll/win32/advapi32",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/include/reactos/idl",
        "sdk/include/reactos/drivers/ksecdd",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["UNICODE", "WINVER=0x502", "_ADVAPI32_", "_UNICODE", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_staticlib("advapi32-rust")
        .c_from_compile_db("advapi32_shims", &["dll/win32/advapi32/eventlogrpc_c.c", "dll/win32/advapi32/lsa_c.c", "dll/win32/advapi32/seclogon_c.c", "dll/win32/advapi32/svcctl_c.c", "dll/win32/advapi32/winreg_c.c"])
        .rc("dll/win32/advapi32/advapi32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/advapi32/advapi32.spec", "advapi32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .import_lib("dll/win32/advapi32_vista/advapi32_vista.spec", "advapi32_vista.dll", "advapi32_vista")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
